import os
import time

from .exception import ParsingFailed, WrongResponse


class GrepLineCounter(object):
    def count(self, out):
        """Method to count found lines in grep command output.

        :param string out:   Output from grep command.

        :return: Number of lines found by grep command.
        :rtype: integer
        """
        result = 0
        for line in out.split("\n"):
            if self._is_multifile_regexp(line):
                number = self._find_number(line)
                result += self._convert_to_int(number)
            else:
                result += self._convert_to_int(line)
        return result

    def _is_multifile_regexp(self, data):
        return ":" in data

    def _find_number(self, data):
        return data.split(':')[1].strip()

    def _convert_to_int(self, data):
        data = data.strip()
        if data:
            return int(data)
        return 0


class GrepCmdBuilder(object):
    def __init__(self, log_pattern):
        """
        :param string log_pattern: Pattern to select all log files.
        """
        self._file_pattern = self._generate_file_pattern(log_pattern)

    def build_find_cmd(self, regexp):
        """Build grep command to find string in files selected by regexp.

        :param string regexp: Python regexp needed to perform the search operation

        :return: Created grep command.
        :rtype: string
        """
        return "grep -rnE '{}' {}".format(regexp, self._file_pattern)

    def build_count_cmd(self, regexp):
        """Build grep command to count strings in files selected by regexp.

        :param string regexp:  Python regexp needed to perform the search operation

        :return: Create grep command.
        :rtype: string
        """
        return "grep -cE '{}' {}".format(regexp, self._file_pattern)

    def _generate_file_pattern(self, log_pattern):
        if "*" not in log_pattern:
            return "'{}'".format(log_pattern)
        else:
            log_dir = os.path.dirname(log_pattern)
            file_pattern = os.path.basename(log_pattern)
            return "'{}'/{}".format(log_dir, file_pattern)


class LogOperator(object):
    """Class to work with syslog file."""

    def __init__(self, ssh_connection, log_pattern):
        """
        :param SSHConnection ssh_connection:  Connected SSHConnection object.
        :param string        log_pattern:     Pattern to select all log files.
        """
        self._log_pattern = log_pattern
        self._ssh_connection = ssh_connection
        self._counter = GrepLineCounter()
        self._builder = GrepCmdBuilder(log_pattern)

    def message_exists(self, regexp):
        """Checks if the specified message exists in the syslog file.

        :param string regexp: Pattern used to find the message in the syslog file.

        :raises: ParsingFailed when regexp cannot match any string.
        """
        process = self._grep_file(regexp)
        out, err, rc = process.read_output(), process.read_error(), process.get_exit_code()
        if err == '' and rc == 0:
            return out
        raise ParsingFailed("Cannot find any string to match regexp ({}) in file ({})".format(regexp, self._log_pattern))

    def wait_for_message(self, regexp, timeout, interval=0.5):
        """Wait for the specified message to appear in the syslog file.

        :param string regexp:   Pattern used to find the message in the syslog file.
        :param float  timeout:  Max. time to wait for message to appear, in seconds.
        :param float  interval: Interval between ssh grep requests.

        :return: Output from grep command.
        :rtype: string

        :raises: ParsingFailed when regexp cannot match any string.
        """
        start_time = time.time()
        while time.time() - start_time < timeout:
            process = self._grep_file(regexp)
            out, err, rc = process.read_output(), process.read_error(), process.get_exit_code()
            if err == '' and rc == 0:
                return out
            time.sleep(interval)
        raise ParsingFailed("Cannot find any string to match regexp ({}) in file ({})".format(regexp, self._log_pattern))

    def count_messages(self, regexp):
        """Returns number of found messages in log file.

        :param string regexp: Pattern used to find the message in the syslog file.

        :return: Returns the number of found messages in the log file.
        :rtype: integer

        :raises: WrongResponse if output format from executed command is wrong.
        """
        process = self._ssh_connection.send_command(self._builder.build_count_cmd(regexp))
        out, rc = process.read_output(), process.get_exit_code()
        try:
            return self._counter.count(out)
        except ValueError as e:
            raise WrongResponse("Cannot count messages for regexp ({}) and file ({})\n".format(regexp, self._log_pattern), out, rc, e)

    def _grep_file(self, regexp):
        return self._ssh_connection.send_command(self._builder.build_find_cmd(regexp))
